-- =============================================================================
-- Tatami — P5a: student identity + invite linking
-- -----------------------------------------------------------------------------
-- Lets an existing student record be claimed by an auth.users account via a
-- one-time invite token (generated by staff). The token pre-encodes the academy
-- and student, so the student needs no academy picker. Account linking + student
-- membership are done in a SECURITY DEFINER RPC so it can write across RLS.
-- Run after 014_master_readonly.sql
-- =============================================================================

-- Link a student record to an auth user (nullable until claimed).
alter table students add column if not exists user_id uuid references auth.users(id);
create index if not exists students_user_id_idx on students (user_id);

-- One-time invites generated by staff.
create table if not exists student_invites (
  token       text primary key,
  academy_id  text not null references academies(id) on delete cascade,
  student_id  text not null references students(id) on delete cascade,
  created_by  uuid references auth.users(id),
  created_at  timestamptz default now(),
  expires_at  timestamptz,
  used_at     timestamptz,
  used_by     uuid references auth.users(id)
);
create index if not exists student_invites_academy_idx on student_invites (academy_id);

alter table student_invites enable row level security;
-- Staff (academy members) create/read invites for their academy. Students never
-- read this table directly — they redeem via the claim RPC below.
drop policy if exists "student_invites_member" on student_invites;
create policy "student_invites_member" on student_invites for all
  using (auth_is_member(academy_id)) with check (auth_is_member(academy_id));

-- Redeem an invite: link the student row to the caller + add a student membership.
-- SECURITY DEFINER so it can write past RLS; validates token/expiry/single-use.
create or replace function claim_student_invite(p_token text)
returns text language plpgsql security definer set search_path = public as $$
declare
  inv student_invites;
  uid uuid := auth.uid();
begin
  if uid is null then raise exception 'not authenticated'; end if;
  select * into inv from student_invites where token = p_token;
  if inv.token is null then raise exception 'invalid invite'; end if;
  if inv.used_at is not null then raise exception 'invite already used'; end if;
  if inv.expires_at is not null and inv.expires_at < now() then raise exception 'invite expired'; end if;

  update students set user_id = uid
    where id = inv.student_id and academy_id = inv.academy_id
      and (user_id is null or user_id = uid);

  insert into academy_members (academy_id, user_id, role)
    values (inv.academy_id, uid, 'student')
    on conflict (academy_id, user_id) do nothing;

  update student_invites set used_at = now(), used_by = uid where token = p_token;
  return inv.academy_id;
end $$;
